   460  static int ReplaceKeyName(char *outbuf, int index, int *outix)
   461  {
   462          // Replace some key-names by single characters, so they can be pronounced in different languages
   463          static MNEM_TAB keynames[] = {
   464                  { "space ",        0xe020 },
   465                  { "tab ",          0xe009 },
   466                  { "underscore ",   0xe05f },
   467                  { "double-quote ", '"' },
   468                  { NULL,            0 }
   469          };
   470
   471          int ix;
   472          int letter;
   473          char *p;
   474
   475          p = &outbuf[index];
   476
   477          if ((letter = LookupMnem(keynames, p)) != 0) {
   478                  ix = utf8_out(letter, p);
   479                  *outix = index + ix;
   480                  return letter;
   481          }
   482          return 0;
   483  }
