   485  static void SetProsodyParameter(int param_type, wchar_t *attr1, PARAM_STACK *sp, PARAM_STACK *param_stack, int *speech_parameters)
   486  {
   487          int value;
   488          int sign;
   489
   490          static const MNEM_TAB mnem_volume[] = {
   491                  { "default", 100 },
   492                  { "silent",    0 },
   493                  { "x-soft",   30 },
   494                  { "soft",     65 },
   495                  { "medium",  100 },
   496                  { "loud",    150 },
   497                  { "x-loud",  230 },
   498                  { NULL,       -1 }
   499          };
   500
   501          static const MNEM_TAB mnem_rate[] = {
   502                  { "default", 100 },
   503                  { "x-slow",   60 },
   504                  { "slow",     80 },
   505                  { "medium",  100 },
   506                  { "fast",    125 },
   507                  { "x-fast",  160 },
   508                  { NULL,       -1 }
   509          };
   510
   511          static const MNEM_TAB mnem_pitch[] = {
   512                  { "default", 100 },
   513                  { "x-low",    70 },
   514                  { "low",      85 },
   515                  { "medium",  100 },
   516                  { "high",    110 },
   517                  { "x-high",  120 },
   518                  { NULL,       -1 }
   519          };
   520
   521          static const MNEM_TAB mnem_range[] = {
   522                  { "default", 100 },
   523                  { "x-low",    20 },
   524                  { "low",      50 },
   525                  { "medium",  100 },
   526                  { "high",    140 },
   527                  { "x-high",  180 },
   528                  { NULL,       -1 }
   529          };
   530
   531          static const MNEM_TAB *mnem_tabs[5] = {
   532                  NULL, mnem_rate, mnem_volume, mnem_pitch, mnem_range
   533          };
   534
   535          if ((value = attrlookup(attr1, mnem_tabs[param_type])) >= 0) {
   536                  // mnemonic specifies a value as a percentage of the base pitch/range/rate/volume
   537                  sp->parameter[param_type] = (param_stack[0].parameter[param_type] * value)/100;
   538          } else {
   539                  sign = attr_prosody_value(param_type, attr1, &value);
   540
   541                  if (sign == 0)
   542                          sp->parameter[param_type] = value; // absolute value in Hz
   543                  else if (sign == 2) {
   544                          // change specified as percentage or in semitones
   545                          sp->parameter[param_type] = (speech_parameters[param_type] * value)/100;
   546                  } else {
   547                          // change specified as plus or minus Hz
   548                          sp->parameter[param_type] = speech_parameters[param_type] + (value*sign);
   549                  }
   550          }
   551  }
